#!/usr/bin/env python3
from pathlib import Path
import sys
root=Path(sys.argv[1] if len(sys.argv)>1 else 'upstream')

def rep(path, old, new, label, count=1):
    p=root/path
    s=p.read_text(encoding='utf-8')
    n=s.count(old)
    if n != count:
        raise SystemExit(f'{path} {label}: expected {count}, got {n}')
    s=s.replace(old,new,count)
    p.write_text(s,encoding='utf-8')

rep(Path('addonProfilerDeep.h'), '    void endTargetScope(void* L);\n', '    void endTargetScope(void* L);\n    void hardReset(void* L);\n', 'deep header')
rep(Path('addonProfilerLite.h'), '    void clearTargetedDeepAddon();\n', '    void clearTargetedDeepAddon();\n    void hardReset();\n', 'lite header')

rep(Path('addonProfilerDeep.cpp'), '    gLuaState = L;\n    clearState(false);\n', '    gLuaState = nullptr;\n    clearState(false);\n', 'start no persistent lua state')
rep(Path('addonProfilerDeep.cpp'), '''    gScopeStartedTicks = 0;\n    gScopeActive = false;\n    gStack.clear();\n}\n''', '''    gScopeStartedTicks = 0;\n    gScopeActive = false;\n    gStack.clear();\n    gLuaState = nullptr;\n}\n''', 'force scope clears lua state')
rep(Path('addonProfilerDeep.cpp'), '''    gScopeActive = true;\n    gScopeStartedTicks = qpcNow();\n''', '''    gLuaState = L;\n    gScopeActive = true;\n    gScopeStartedTicks = qpcNow();\n''', 'scope owns lua state only while active')
rep(Path('addonProfilerDeep.cpp'), '    if (gScopeActive) forceEndScope(gLuaState, true);\n', '    if (gScopeActive && gLuaState) forceEndScope(gLuaState, true);\n', 'frame safe cleanup')

rep(Path('addonProfilerDeep.cpp'), '''static void stopProfiler(void* L) {\n    forceEndScope(L, true);\n    addonProfilerLite::clearTargetedDeepAddon();\n    QueryPerformanceCounter(&gSessionEnded);\n    gRunning = false;\n    gDeep = false;\n}\n''', '''static void destroySessionResources() {\n    std::unordered_map<std::string, Aggregate>().swap(gAddons);\n    std::unordered_map<std::string, Aggregate>().swap(gFiles);\n    std::unordered_map<std::string, Aggregate>().swap(gFunctions);\n    std::vector<CallFrame>().swap(gStack);\n    std::deque<LongFrame>().swap(gLongFrames);\n    gFunctionOverflow = false;\n    gTargetAddon.clear();\n    gLuaState = nullptr;\n    gScopeActive = false;\n    gScopeStartedTicks = 0;\n    gNextSampleTicks = 0;\n    gSampledScopeTicks = 0;\n    gSampledScopes = 0;\n    gSkippedScopes = 0;\n    gHookBusySkips = 0;\n    gAbortedScopes = 0;\n    gSessionStarted.QuadPart = 0;\n    gSessionEnded.QuadPart = 0;\n    clearState(false);\n}\n\nstatic void stopProfiler(void* L) {\n    forceEndScope(L, true);\n    addonProfilerLite::clearTargetedDeepAddon();\n    gRunning = false;\n    gDeep = false;\n    destroySessionResources();\n}\n''', 'destroy deep resources on stop')

rep(Path('addonProfilerDeep.cpp'), '''void endTargetScope(void* L) {\n    forceEndScope(L, false);\n}\n\nvoid onFrameBoundary() {\n''', '''void endTargetScope(void* L) {\n    forceEndScope(L, false);\n}\n\nvoid hardReset(void* L) {\n    // Never dereference a stale gLuaState from a prior UI VM. Only inspect the\n    // current Lua state supplied by the caller while that state is still valid.\n    if (L && lua_gethook(L) == &profilerHook) lua_sethook(L, nullptr, 0, 0);\n    gScopeActive = false;\n    gScopeStartedTicks = 0;\n    gLuaState = nullptr;\n    gRunning = false;\n    gDeep = false;\n    addonProfilerLite::clearTargetedDeepAddon();\n    destroySessionResources();\n}\n\nvoid onFrameBoundary() {\n''', 'deep hard reset export')

rep(Path('addonProfilerDeep.cpp'), '''    if (sub == "reset") {\n        markCurrentCallProfilerApi();\n        if (gRunning) { lua_pushboolean(L, 0); lua_pushstring(L, "STOP_BEFORE_RESET"); return 2; }\n        clearState(false);\n        gTargetAddon.clear();\n        gSessionStarted.QuadPart = gSessionEnded.QuadPart = 0;\n        gSampledScopeTicks = gSampledScopes = gSkippedScopes = gHookBusySkips = gAbortedScopes = 0;\n        lua_pushboolean(L, 1);\n        return 1;\n    }\n''', '''    if (sub == "reset") {\n        markCurrentCallProfilerApi();\n        if (gRunning) { lua_pushboolean(L, 0); lua_pushstring(L, "STOP_BEFORE_RESET"); return 2; }\n        destroySessionResources();\n        lua_pushboolean(L, 1);\n        return 1;\n    }\n    if (sub == "hardreset") {\n        hardReset(L);\n        lua_pushboolean(L, 1);\n        return 1;\n    }\n''', 'deep hard reset api')

rep(Path('addonProfilerLite.cpp'), 'static bool gRunning = false;\n', 'static bool gRunning = false;\nstatic std::uint64_t gSessionGeneration = 1;\n', 'lite session generation')

rep(Path('addonProfilerLite.cpp'), '''static int __fastcall wrappedHandler(void* L) {\n    const int argc = lua_gettop(L);\n    const int token = static_cast<int>(lua_tonumber(L, kLuaUpvalue2));\n    const bool valid = token > 0 && static_cast<std::size_t>(token) <= gHandlers.size();\n\n    if (!gRunning || !valid) {\n        lua_pushvalue(L, kLuaUpvalue1);\n        pLuaInsert(L, 1);\n        pLuaCall(L, argc, kLuaMultiRet);\n        return lua_gettop(L);\n    }\n\n    HandlerRecord& h = gHandlers[static_cast<std::size_t>(token - 1)];\n    const bool deepIsolation = deepIsolationActive();\n    const bool deepCandidate = (gTargetedDeepAddonIndex == h.addonIndex);\n    const bool deepScope = deepCandidate ? addonProfilerDeep::beginTargetScope(L) : false;\n\n    const std::uint64_t bookkeepingStart = qpc();\n    lua_pushvalue(L, kLuaUpvalue1);\n    pLuaInsert(L, 1);\n    const std::uint64_t callStart = qpc();\n    pLuaCall(L, argc, kLuaMultiRet);\n    const std::uint64_t callEnd = qpc();\n    if (deepScope) addonProfilerDeep::endTargetScope(L);\n    const std::uint64_t elapsed = callEnd >= callStart ? callEnd - callStart : 0;\n\n    const std::uint64_t bookkeepingEnd = qpc();\n    if (!deepIsolation) {\n        addStat(h.s, h.kind, elapsed);\n        if (h.addonIndex < gAddons.size()) addStat(gAddons[h.addonIndex].s, h.kind, elapsed);\n        if (h.fileIndex < gFiles.size()) addStat(gFiles[h.fileIndex].s, h.kind, elapsed);\n        gWindowMeasuredTicks += elapsed;\n        const std::uint64_t pre = callStart >= bookkeepingStart ? callStart - bookkeepingStart : 0;\n        const std::uint64_t post = bookkeepingEnd >= callEnd ? bookkeepingEnd - callEnd : 0;\n        gWindowBookkeepingTicks += pre + post;\n    }\n    return lua_gettop(L);\n}\n''', '''static int __fastcall wrappedHandler(void* L) {\n    const int argc = lua_gettop(L);\n    const int token = static_cast<int>(lua_tonumber(L, kLuaUpvalue2));\n    const std::size_t handlerIndex = token > 0 ? static_cast<std::size_t>(token - 1) : static_cast<std::size_t>(-1);\n    const bool valid = token > 0 && handlerIndex < gHandlers.size();\n\n    if (!gRunning || !valid) {\n        lua_pushvalue(L, kLuaUpvalue1);\n        pLuaInsert(L, 1);\n        pLuaCall(L, argc, kLuaMultiRet);\n        return lua_gettop(L);\n    }\n\n    // Copy metadata before calling Lua. PLAYER_LEAVING_WORLD may hard-reset the\n    // profiler from inside the original handler and free gHandlers immediately.\n    const std::uint64_t generation = gSessionGeneration;\n    const std::size_t addonIndex = gHandlers[handlerIndex].addonIndex;\n    const std::size_t fileIndex = gHandlers[handlerIndex].fileIndex;\n    const Kind kind = gHandlers[handlerIndex].kind;\n    const bool deepIsolation = deepIsolationActive();\n    const bool deepCandidate = (gTargetedDeepAddonIndex == addonIndex);\n    const bool deepScope = deepCandidate ? addonProfilerDeep::beginTargetScope(L) : false;\n\n    const std::uint64_t bookkeepingStart = qpc();\n    lua_pushvalue(L, kLuaUpvalue1);\n    pLuaInsert(L, 1);\n    const std::uint64_t callStart = qpc();\n    pLuaCall(L, argc, kLuaMultiRet);\n    const std::uint64_t callEnd = qpc();\n    if (deepScope) addonProfilerDeep::endTargetScope(L);\n    const std::uint64_t elapsed = callEnd >= callStart ? callEnd - callStart : 0;\n\n    const std::uint64_t bookkeepingEnd = qpc();\n    if (!deepIsolation && generation == gSessionGeneration && gRunning && handlerIndex < gHandlers.size()) {\n        addStat(gHandlers[handlerIndex].s, kind, elapsed);\n        if (addonIndex < gAddons.size()) addStat(gAddons[addonIndex].s, kind, elapsed);\n        if (fileIndex < gFiles.size()) addStat(gFiles[fileIndex].s, kind, elapsed);\n        gWindowMeasuredTicks += elapsed;\n        const std::uint64_t pre = callStart >= bookkeepingStart ? callStart - bookkeepingStart : 0;\n        const std::uint64_t post = bookkeepingEnd >= callEnd ? bookkeepingEnd - callEnd : 0;\n        gWindowBookkeepingTicks += pre + post;\n    }\n    return lua_gettop(L);\n}\n''', 'generation-safe wrapper')

rep(Path('addonProfilerLite.cpp'), '''void clearTargetedDeepAddon() {\n    discardActiveWindowKeepLast();\n    gTargetedDeepAddonIndex = static_cast<std::size_t>(-1);\n}\n\nvoid onFrameBoundary() {\n''', '''void clearTargetedDeepAddon() {\n    discardActiveWindowKeepLast();\n    gTargetedDeepAddonIndex = static_cast<std::size_t>(-1);\n}\n\nvoid hardReset() {\n    gRunning = false;\n    gTargetedDeepAddonIndex = static_cast<std::size_t>(-1);\n    ++gSessionGeneration;\n    if (gSessionGeneration == 0) gSessionGeneration = 1;\n\n    std::vector<AddonStat>().swap(gAddons);\n    std::vector<FileStat>().swap(gFiles);\n    std::vector<HandlerRecord>().swap(gHandlers);\n    std::unordered_map<std::string, std::size_t>().swap(gAddonIndex);\n    std::unordered_map<std::string, std::size_t>().swap(gFileIndex);\n    std::deque<LongFrame>().swap(gLongFrames);\n\n    gWindowMeasuredTicks = gLastMeasuredTicks = 0;\n    gWindowUnattributedTicks = gLastUnattributedTicks = 0;\n    gWindowBookkeepingTicks = gLastBookkeepingTicks = 0;\n    gWindowBoundaryTicks = gLastBoundaryTicks = 0;\n    gLastSnapshotTicks = 0;\n    gWindowFrames = gLastFrames = 0;\n    gWindowFrameTicks = gLastFrameTicks = 0;\n    gWindowPeakFrameTicks = gLastPeakFrameTicks = 0;\n    gLastWindowSeconds = 0.0;\n    gTotalLongFrames = 0;\n    gLastFrameBoundary.QuadPart = 0;\n    gMemorySampleTime.QuadPart = 0;\n    gLastGcTime.QuadPart = 0;\n    gLastLuaMemoryKb = -1.0;\n    gLuaMemoryKb = -1.0;\n    gAllocationRateKbSec = 0.0;\n    gGcDetectedCount = 0;\n    QueryPerformanceCounter(&gWindowStarted);\n}\n\nvoid onFrameBoundary() {\n''', 'lite hard reset export')

rep(Path('addonProfilerLite.cpp'), '    if(sub=="reset"){resetStats();lua_pushboolean(L,1);return 1;}\n', '    if(sub=="reset"){resetStats();lua_pushboolean(L,1);return 1;}\n    if(sub=="hardreset"){hardReset();lua_pushboolean(L,1);return 1;}\n', 'lite hard reset api')
rep(Path('addonProfilerLite.cpp'), 'pushNumberField(L,"wrappedHandlerCount",(double)gHandlers.size());pushBoolField(L,"deepIsolation",deepIsolationActive());return 1;\n', 'pushNumberField(L,"wrappedHandlerCount",(double)gHandlers.size());pushBoolField(L,"deepIsolation",deepIsolationActive());pushNumberField(L,"sessionGeneration",(double)gSessionGeneration);return 1;\n', 'status session generation')

rep(Path('dllmain.cpp'), '''            if (subcmd == "PLAYER_ENTERING_WORLD") {\n                onPlayerEnteringWorld();\n                lua_pushboolean(L, true);\n                return 1;\n            }\n            if (subcmd == "PLAYER_LEAVING_WORLD") {\n                onPlayerLeavingWorld();\n                lua_pushboolean(L, true);\n                return 1;\n            }\n''', '''            if (subcmd == "PLAYER_ENTERING_WORLD") {\n                // New UI/Lua world: never carry profiler pointers or wrapper metadata across sessions.\n                addonProfilerDeep::hardReset(L);\n                addonProfilerLite::hardReset();\n                onPlayerEnteringWorld();\n                lua_pushboolean(L, true);\n                return 1;\n            }\n            if (subcmd == "PLAYER_LEAVING_WORLD") {\n                // Current Lua state is still valid here, so remove our hook before the UI VM is torn down.\n                addonProfilerDeep::hardReset(L);\n                addonProfilerLite::hardReset();\n                onPlayerLeavingWorld();\n                lua_pushboolean(L, true);\n                return 1;\n            }\n''', 'dll world lifecycle wiring')

